binary_search <- function(arr, target) {
  left <- 1
  right <- length(arr)
  while (left <= right) {
    mid <- floor((left + right) / 2)
    if (arr[mid] == target) {
      return(mid)  # نرجع الفهرس مباشرة عند الوجد
    } else if (arr[mid] < target) {
      left <- mid + 1
    } else {
      right <- mid - 1
    }
  }
  return(-1)  # لم يوجد الهدف
}

