bubble_sort <- function(arr) {
  n <- length(arr)
  swaps <- 0
  # نمرر على العناصر حتى آخر عنصر غير مرتب
  for (i in 1:(n-1)) {
    for (j in 1:(n-i)) {
      if (arr[j] > arr[j+1]) {
        # تبادل القيم
        temp <- arr[j]
        arr[j] <- arr[j+1]
        arr[j+1] <- temp
        swaps <- swaps + 1
      }
    }
  }
  cat("Sorted:", arr, "\n")
  cat("Swaps:", swaps, "\n")
}

