fibonacci <- function(n) {
  if (n <= 1) return(n)
  # نخزن القيم السابقة لتجنب إعادة الحساب
  fib <- c(0, 1)
  for (i in 2:n) {
    fib[i+1] <- fib[i] + fib[i-1]
  }
  return(fib[n+1])
}

