fib <- function(n) {
  if (n <= 0) return(c())
  if (n == 1) return(0)
  if (n == 2) return(c(0, 1))
  seq <- c(0, 1)
  for (i in 3:n) {
    seq <- c(seq, seq[i-1] + seq[i-2])
  }
  return(seq)
}

