bfs <- function(graph, start) {
  visited <- setNames(rep(FALSE, length(graph)), names(graph))
  queue <- c(start)
  visited[[start]] <- TRUE
  order <- c()
  while (length(queue) > 0) {
    node <- queue[1]
    queue <- queue[-1]
    order <- c(order, node)
    for (nei in graph[[node]]) {
      if (!visited[[nei]]) {
        visited[[nei]] <- TRUE
        queue <- c(queue, nei)
      }
    }
  }
  order
}

