insertion_sort <- function(arr) {
  n <- length(arr)
  # نبدأ من العنصر الثاني لأن الأول يعتبر مرتبًا
  for (i in 2:n) {
    key <- arr[i]
    j <- i - 1
    # ننقل العناصر الأكبر من المفتاح إلى اليمين
    while (j >= 1 && arr[j] > key) {
      arr[j + 1] <- arr[j]
      j <- j - 1
    }
    arr[j + 1] <- key
  }
  return(arr)
}

