merge_sort <- function(arr) {
  if (length(arr) <= 1) return(arr)  # حالة القاعدة
  mid <- length(arr) %/% 2
  left <- merge_sort(arr[1:mid])
  right <- merge_sort(arr[(mid+1):length(arr)])
  return(merge(left, right))
}

merge <- function(a, b) {
  result <- c()
  i <- 1; j <- 1
  # ندمج حتى نستنفد إحدى القائمتين
  while (i <= length(a) && j <= length(b)) {
    if (a[i] <= b[j]) {
      result <- c(result, a[i])
      i <- i + 1
    } else {
      result <- c(result, b[j])
      j <- j + 1
    }
  }
  # نضيف الباقي
  if (i <= length(a)) result <- c(result, a[i:length(a)])
  if (j <= length(b)) result <- c(result, b[j:length(b)])
  return(result)
}

