to_pig_latin <- function(word) {
  first <- substr(word, 1, 1)
  rest <- substr(word, 2, nchar(word))
  # لماذا؟ لأن قاعدة Pig Latin تنقل الحرف الأول إلى النهاية وتضيف "ay"
  return(paste0(rest, first, "ay"))
}

